import numpy as np
import time
from scipy.signal import fftconvolve


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    l2 = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    l1 = s * s
    linf = L.max()
    if linf <= 0:
        return -1.0
    return l2 / (l1 * linf)


def _trapezoid(N, a, b):
    h = np.zeros(N)
    c = (N - 1) / 2.0
    for i in range(N):
        d = abs(i - c)
        if d <= a:
            h[i] = 1.0
        elif d <= a + b:
            h[i] = (a + b - d) / b
        else:
            h[i] = 0.0
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    N = 50000
    best = None
    best_score = -1.0
    a_vals = [0, 500, 1000, 2000, 4000, 8000]
    b_vals = [500, 1000, 2000, 4000, 8000, 16000]
    for a in a_vals:
        for b in b_vals:
            if time.process_time() - t0 > budget_seconds * 0.8:
                break
            h = _trapezoid(N, a, b)
            sc = _R(h)
            if sc > best_score:
                best_score = sc
                best = h
        if time.process_time() - t0 > budget_seconds * 0.8:
            break

    # compare with start
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.any(s > 0):
            sc_s = _R(s)
            if sc_s > best_score:
                return s

    if best is None:
        return np.ones(50)
    return best
